// index.mjs — the public entry point. `createDriver()` assembles the whole fleet driver
// (log + fences + worktree manager + trust gate + router + story + coordinator) into one
// runnable object, wiring the real modules to the coordinator's dependency contract.
// This is the "how to run the whole thing" — a program, authenticated web northbound, or future
// MCP adapter calls the coordinator's commands; everything underneath is deterministic code.

import { join, basename, sep } from 'node:path';
import { execFileSync } from 'node:child_process';
import { existsSync, realpathSync, rmSync } from 'node:fs';

import { Log } from './log.mjs';
import { FenceTable } from './fence.mjs';
import { Coordinator } from './coordinator.mjs';
import * as worktreeMod from './worktree.mjs';
import { verify, accept } from './referee.mjs';
import { AdaptiveRouter } from './router.mjs';
import { StoryCompiler } from './story.mjs';
import { RuntimeIsolation } from './runtime-isolation.mjs';
import { CoordinationStore } from './coordination-store.mjs';

export { Coordinator, ModelSelectionError, SessionSelectionError, IntegrationError, ReviewSelectionError, PublicationError } from './coordinator.mjs';
export { MockAdapter, CodexAdapter, ClaudeAdapter, GlmAdapter } from './adapter.mjs';
// SC2: the session tier IS the product surface — constructible from the entry point.
export { ClaudeSessionCli, GlmSessionCli } from './claude-session.mjs';
export { CodexAppServerCli } from './codex-appserver.mjs';
export { GrokAcpCli } from './grok-acp.mjs';
export { createBrief } from './messages.mjs';
export { verify, accept } from './referee.mjs';
export { AdaptiveRouter } from './router.mjs';
export { RuntimeIsolation, isSecretEnvName } from './runtime-isolation.mjs';
export { CoordinationStore, CoordinationIntegrityError, CoordinationRefusal, coordinationForLog } from './coordination-store.mjs';
export { WebNorthbound, createAuthenticatedWebServer, validateWebCommandEnvelope } from './web-northbound.mjs';
export { WebEventStream } from './web-stream.mjs';
export { WebSessionStore, WebSessionIntegrityError, WEB_SESSION_COOKIE_NAME } from './web-auth.mjs';
export { AtlasStructuralDelta } from './atlas-structural.mjs';
export { AtlasCodeIndex } from './atlas-index.mjs';

/** worktree.mjs's real functions wrapped into the coordinator's manager interface. */
function worktreeManager(repoRoot, opts = {}) {
  return {
    async create(taskId) {
      const base = await worktreeMod.pinBaseSha(repoRoot, {});
      const r = await worktreeMod.createFromBase(repoRoot, taskId, base.sha, { dependencyDirs: opts.workerDependencyDirs ?? [] });
      return { path: r.dir, branch: r.branch, baseSha: r.baseSha };
    },
    async capture(worktreePath, opts = {}) {
      return worktreeMod.captureCommit(repoRoot, basename(worktreePath), { vendor: opts.vendor, model: opts.model });
    },
    async createVerifyWorktree(taskId, sha) {
      const r = await worktreeMod.freshVerifySandbox(repoRoot, taskId, sha, { dependencyDirs: opts.verifyDependencyDirs ?? [] });
      return { path: r.dir ?? r.path };
    },
    async createBaseVerifyWorktree(taskId, sha) {
      const r = await worktreeMod.freshVerifySandbox(repoRoot, `${taskId}-base`, sha, { dependencyDirs: opts.verifyDependencyDirs ?? [] });
      return { path: r.dir ?? r.path };
    },
    async changedLines(baseSha, resultSha) {
      return worktreeMod.changedLines(repoRoot, baseSha, resultSha);
    },
    async integrate(sha, opts = {}) {
      const strategy = opts.strategy ?? 'ff-only';
      if (strategy !== 'ff-only') throw new Error(`unsupported integration strategy: ${strategy}`);
      const dirty = execFileSync('git', ['status', '--porcelain'], { cwd: repoRoot, encoding: 'utf8' }).trim();
      if (dirty) throw new Error('main checkout is dirty');
      const beforeSha = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: repoRoot, encoding: 'utf8' }).trim();
      execFileSync('git', ['merge', '--ff-only', sha], { cwd: repoRoot, stdio: 'pipe' });
      const afterSha = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: repoRoot, encoding: 'utf8' }).trim();
      return { beforeSha, resultSha: sha, afterSha };
    },
    async retainResult(sha) {
      const ref = `refs/baton/results/${sha}`;
      execFileSync('git', ['update-ref', ref, sha], { cwd: repoRoot, stdio: 'ignore' });
      return ref;
    },
    async releaseResult(ref) {
      execFileSync('git', ['update-ref', '-d', ref], { cwd: repoRoot, stdio: 'ignore' });
    },
    async removeVerifyWorktree(verifyPath) {
      try { execFileSync('git', ['worktree', 'remove', '--force', verifyPath], { cwd: repoRoot, stdio: 'ignore' }); } catch { /* noop */ }
      try { rmSync(verifyPath, { recursive: true, force: true }); } catch { /* noop */ }
    },
    // Terminal policy cleanup owns non-evidence task branches as well as their checkout/metadata.
    async remove(taskId) { try { await worktreeMod.reap(repoRoot, taskId, { force: true, deleteBranch: true }); } catch { /* noop */ } },
    async validateSessionContext(context) {
      try {
        if (!existsSync(context.worktree)) return { ok: false, reason: 'session worktree no longer exists' };
        const root = realpathSync(repoRoot);
        const worktree = realpathSync(context.worktree);
        const managedRoot = realpathSync(join(repoRoot, '.baton', 'wt'));
        if (context.repoRoot && realpathSync(context.repoRoot) !== root) return { ok: false, reason: 'session repository identity mismatch' };
        if (worktree !== managedRoot && !worktree.startsWith(`${managedRoot}${sep}`)) return { ok: false, reason: 'session worktree is outside Baton ownership' };
        if (context.ownerTaskId && basename(worktree) !== context.ownerTaskId) return { ok: false, reason: 'session worktree owner mismatch' };
        const top = execFileSync('git', ['rev-parse', '--show-toplevel'], { cwd: worktree, encoding: 'utf8' }).trim();
        if (realpathSync(top) !== worktree) return { ok: false, reason: 'session path is not the recorded git worktree root' };
        if (context.branch) {
          const branch = execFileSync('git', ['branch', '--show-current'], { cwd: worktree, encoding: 'utf8' }).trim();
          if (branch !== context.branch) return { ok: false, reason: 'session worktree branch mismatch' };
        }
        if (context.baseSha) {
          execFileSync('git', ['merge-base', '--is-ancestor', context.baseSha, 'HEAD'], { cwd: worktree, stdio: 'ignore' });
        }
        return { ok: true };
      } catch (err) {
        return { ok: false, reason: `session context validation failed: ${err?.message ?? err}` };
      }
    },
    async reconcile() { try { await worktreeMod.reconcile(repoRoot, []); } catch { /* noop */ } },
  };
}

/** The real hardened referee in the coordinator's fn contract (maps task.worktree -> workerWorktreeDir, string sandbox -> {dir}). */
function refereeFn(task, result, opts) {
  const mapped = { ...task, workerWorktreeDir: task.worktree, verification: opts.pinnedVerification };
  return verify(mapped, result, { dir: opts.sandbox }, {
    ...(opts.baseSandbox ? { baseSandbox: { dir: opts.baseSandbox } } : {}),
  });
}

/**
 * Assemble a runnable fleet driver.
 * @param {{repoRoot:string, logDir:string, adapters:Record<string,object>, now?:()=>number,
 *          approvalTimeoutMs?:number, stopDeadlineMs?:number}} opts
 * @returns {{coordinator:Coordinator, story:StoryCompiler, router:AdaptiveRouter, log:Log}}
 */
export function createDriver(opts) {
  const now = opts.now ?? Date.now;
  const log = new Log(opts.logDir, () => new Date(now()).toISOString());
  const fences = new FenceTable();
  const router = new AdaptiveRouter({ mode: 'adaptive', now });
  const story = new StoryCompiler({ now });
  const runtimeScopes = opts.runtimeScopes ?? new RuntimeIsolation({
    repoRoot: opts.repoRoot,
    ...(opts.runtimeIsolation ?? {}),
  });
  const coordination = opts.coordination ?? new CoordinationStore(join(opts.logDir, 'coordination'), {
    operationalRead: (worker, seq) => log.read(worker, seq).find((event) => event.seq === seq) ?? null,
  });
  const publisher = Object.hasOwn(opts, 'publisher') ? opts.publisher : async ({ remote, ref, sha }) => {
    execFileSync('git', ['push', '--porcelain', remote, `${sha}:${ref}`], { cwd: opts.repoRoot, stdio: 'ignore' });
    return { transport: 'git-push' };
  };

  // C2/D5: real selection via router.pick(task, candidates) over the ceiling-feasible
  // set — no first-fit fallback. `pick()` already returns null when nothing is eligible,
  // which is exactly "queue" (the coordinator's own ceiling re-check catches it too).
  const route = (task, cards, inFlight) => {
    let feasible = Object.keys(opts.adapters).filter((v) => (inFlight[v] ?? 0) < cards[v].concurrencyCeiling);
    // SC7: the explicit capability tag beats operator folklore — when any feasible card lists
    // the task's taskType in nonRefuserFor, restrict to those vendors. Feasibility is computed
    // FIRST (a capable-but-saturated vendor never restricts) and an unlisted taskType leaves
    // the pool untouched — the restriction can never strand a task.
    const capable = feasible.filter((v) => Array.isArray(cards[v].nonRefuserFor) && cards[v].nonRefuserFor.includes(task.taskType));
    if (capable.length > 0) feasible = capable;
    const candidateKey = (v) => {
      const base = `${cards[v].harness}@${cards[v].version}`;
      return cards[v].modelSelection?.resolved ? `${base}#${cards[v].modelSelection.resolved}` : base;
    };
    const candidates = feasible.map((v) => ({
      modelVersion: candidateKey(v),
      family: cards[v].modelSelection?.family ?? 'default',
      concurrencyCeiling: cards[v].concurrencyCeiling,
      inFlight: inFlight[v] ?? 0,
    }));
    const chosen = router.pick(task, candidates);
    if (!chosen) return null;
    // First-listed feasible vendor wins a modelVersion collision: two adapters CAN share
    // harness@version (e.g. one-shot ClaudeCli and session ClaudeSessionCli for the same CLI),
    // and a last-wins Map would silently flip which vendor key receives the dispatch.
    return feasible.find((v) => candidateKey(v) === chosen) ?? null;
  };
  route.record = (mv, tt, win) => router.record(mv, tt, win);

  const coordinator = new Coordinator({
    log, fences,
    adapters: opts.adapters,
    worktrees: worktreeManager(opts.repoRoot, {
      workerDependencyDirs: opts.workerDependencyDirs,
      verifyDependencyDirs: opts.verifyDependencyDirs,
    }),
    runtimeScopes,
    coordination,
    repoRoot: opts.repoRoot,
    referee: refereeFn,
    route,
    accept: (verdict, acceptOpts) => accept(verdict, acceptOpts),
    acceptOpts: {
      requireRedGreen: opts.requireRedGreen ?? false,
      requireCoverage: opts.requireCoverage ?? false,
      requireMutation: opts.requireMutation ?? false,
    },
    requireIndependentOracle: opts.requireIndependentOracle ?? false,
    publisher,
    story: { record: (e) => story.ingest(e) },
    now,
    approvalTimeoutMs: opts.approvalTimeoutMs ?? 60000,
    stopDeadlineMs: opts.stopDeadlineMs ?? 15000,
    recoveryTimeoutMs: opts.recoveryTimeoutMs ?? 15000,
    budgetPolicy: opts.budgetPolicy,
    watchdog: opts.watchdog,
  });

  return { coordinator, story, router, log, coordination };
}
// coordinator.mjs — the main loop and the 8 commands (spawn/send/wait/respond/interrupt/
// result/list/kill). Owns the worker pool, dispatches ready tasks, carries commands
// reliably (fence-checked), enforces two-phase stop, single-consumer approvals, and the
// trust gate. See spec/IMPLEMENTATION.md (CLUSTER 1 — CORE) and spec/RECONCILIATION.md
// (D1/D9/D10/D11), which is authoritative over any conflicting cluster spec.

import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { isAbsolute, join, relative } from 'node:path';
import { Cursor } from './log.mjs';
import { createBrief, createDigest, wrapFact, wrapProse } from './messages.mjs';

// ---------------------------------------------------------------------------
// Error taxonomy (thrown, not returned) — programmer-error / precondition failures.
// ---------------------------------------------------------------------------

export class WorkerNotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'WorkerNotFoundError';
  }
}

export class DuplicateTaskIdError extends Error {
  constructor(message) {
    super(message);
    this.name = 'DuplicateTaskIdError';
  }
}

export class UnknownVendorError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnknownVendorError';
  }
}

export class ModelSelectionError extends Error {
  constructor(message, code = 'model_unavailable') {
    super(message);
    this.name = 'ModelSelectionError';
    this.code = code;
  }
}

export class SessionSelectionError extends Error {
  constructor(message, code = 'session_mode_unavailable') {
    super(message);
    this.name = 'SessionSelectionError';
    this.code = code;
  }
}

export class IntegrationError extends Error {
  constructor(message, code = 'integration_refused') {
    super(message);
    this.name = 'IntegrationError';
    this.code = code;
  }
}

export class ReviewSelectionError extends Error {
  constructor(message, code = 'review_refused') {
    super(message);
    this.name = 'ReviewSelectionError';
    this.code = code;
  }
}

export class PublicationError extends Error {
  constructor(message, code = 'publication_refused') {
    super(message);
    this.name = 'PublicationError';
    this.code = code;
  }
}

export class DependencyCycleError extends Error {
  constructor(message) {
    super(message);
    this.name = 'DependencyCycleError';
  }
}

// SC13: cancellation is terminal too. No late spawn/delivery/turn continuation may revive it.
const TERMINAL_TASK_STATUSES = new Set(['completed', 'failed', 'cancelled']);
const COORDINATION_MUTATORS = new Set([
  'createTask', 'claimTask', 'transitionTask', 'transitionTaskWithArtifacts', 'mapOperationalEvent',
  'recordDriver', 'completeIntegration', 'completePublication', 'registerArtifact', 'supersedeArtifact', 'claimScratch', 'postScratchFact',
  'readScratch', 'expireScratchClaim', 'expireScratchFact', 'addKnowledgeNode', 'promoteKnowledgeNode',
  'addKnowledgeEdge', 'readKnowledge', 'invalidateKnowledge', 'recordContamination',
]);

function minimalBrief() {
  return { goal: '', constraints: [], pathScope: [], definitionOfDone: '', verification: { command: 'true', expectExit: 0 }, budget: { tokens: 0, usd: 0, wallMin: 0 } };
}

function noop() {}

function globRegex(glob) {
  let re = '^';
  const text = String(glob);
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    if (char === '*') {
      if (text[i + 1] === '*') {
        re += '.*';
        i += 1;
        if (text[i + 1] === '/') i += 1;
      } else re += '[^/]*';
    } else if (char === '?') re += '[^/]';
    else if ('.+^${}()|[]\\'.includes(char)) re += `\\${char}`;
    else re += char;
  }
  return new RegExp(`${re}$`);
}

function pathInScope(scopes, path) {
  if (!Array.isArray(scopes) || scopes.length === 0) return true;
  return scopes.some((scope) => scope === '**' || scope === '.' || scope === './' || globRegex(scope).test(path));
}

function normalizeModelPolicy(model, policy) {
  if (model !== undefined && (typeof model !== 'string' || model.length === 0)) {
    throw new ModelSelectionError('model must be a non-empty exact identifier', 'invalid_model');
  }
  if (policy == null) return null;
  if (typeof policy !== 'object' || Array.isArray(policy)) {
    throw new ModelSelectionError('modelPolicy must be an object', 'invalid_model_policy');
  }
  const normalized = {};
  for (const key of ['allow', 'deny', 'prefer', 'allowFamilies', 'denyFamilies']) {
    if (policy[key] === undefined) continue;
    if (!Array.isArray(policy[key]) || policy[key].some((v) => typeof v !== 'string' || v.length === 0)) {
      throw new ModelSelectionError(`modelPolicy.${key} must be a non-empty string[]`, 'invalid_model_policy');
    }
    normalized[key] = [...policy[key]];
  }
  for (const key of ['reasoningEffort', 'serviceTier']) {
    if (policy[key] !== undefined && (typeof policy[key] !== 'string' || policy[key].length === 0)) {
      throw new ModelSelectionError(`modelPolicy.${key} must be a non-empty string`, 'invalid_model_policy');
    }
    if (policy[key] !== undefined) normalized[key] = policy[key];
  }
  if (model !== undefined && normalized.allow && !normalized.allow.includes(model)) {
    throw new ModelSelectionError(`exact model "${model}" is excluded by modelPolicy.allow`, 'model_policy_conflict');
  }
  if (model !== undefined && normalized.deny?.includes(model)) {
    throw new ModelSelectionError(`exact model "${model}" is excluded by modelPolicy.deny`, 'model_policy_conflict');
  }
  return Object.freeze(normalized);
}

function cardAcceptsExactModel(card, model, { explicit = false } = {}) {
  const selection = card?.modelSelection;
  if (!selection || selection.mode !== 'exact') return false;
  if (Array.isArray(selection.available)) return selection.available.includes(model);
  if (explicit) return true; // native wire is authoritative when discovery is unavailable
  if (selection.acceptedAliases?.includes(model)) return true;
  return (selection.acceptedPrefixes ?? []).some((prefix) => model.startsWith(prefix));
}

function resolveCardModel(card, requested, policy, { explicit = false } = {}) {
  const selection = card?.modelSelection;
  const family = selection?.family ?? null;
  if (policy?.allowFamilies && !policy.allowFamilies.includes(family)) return { ok: false, reason: 'family_not_allowed' };
  if (policy?.denyFamilies?.includes(family)) return { ok: false, reason: 'family_denied' };
  if (policy?.reasoningEffort && !selection?.reasoningEffort?.includes(policy.reasoningEffort)) {
    return { ok: false, reason: 'reasoning_effort_unsupported' };
  }
  if (policy?.serviceTier && !selection?.serviceTier?.includes(policy.serviceTier)) {
    return { ok: false, reason: 'service_tier_unsupported' };
  }

  if (requested != null) {
    return cardAcceptsExactModel(card, requested, { explicit })
      ? { ok: true, model: requested }
      : { ok: false, reason: 'model_unavailable' };
  }

  const permitted = (model) => model == null
    ? !(policy?.allow?.length)
    : (!policy?.allow || policy.allow.includes(model)) && !policy?.deny?.includes(model);
  for (const preferred of policy?.prefer ?? []) {
    if (permitted(preferred) && cardAcceptsExactModel(card, preferred, { explicit })) return { ok: true, model: preferred };
  }
  const configured = selection?.configuredDefault ?? null;
  if (permitted(configured)) return { ok: true, model: configured };
  if (Array.isArray(selection?.available)) {
    const candidate = selection.available.find(permitted);
    if (candidate !== undefined) return { ok: true, model: candidate };
  }
  return { ok: false, reason: 'model_policy_unmatched' };
}

function modelRouteKey(card, model) {
  const harness = card ? `${card.harness}@${card.version}` : 'unknown';
  return model ? `${harness}#${model}` : harness;
}

function normalizeSessionRequest(request) {
  if (request == null) return Object.freeze({ mode: 'new' });
  if (typeof request !== 'object' || Array.isArray(request)) {
    throw new SessionSelectionError('session must be an object', 'invalid_session_request');
  }
  const mode = request.mode ?? 'new';
  if (!['new', 'resume', 'fork'].includes(mode)) {
    throw new SessionSelectionError(`unknown session mode "${mode}"`, 'invalid_session_request');
  }
  if (mode !== 'new' && (typeof request.id !== 'string' || request.id.length === 0)) {
    throw new SessionSelectionError(`session.${mode} requires a non-empty id`, 'invalid_session_request');
  }
  if (request.lastTurnId !== undefined && (mode !== 'fork' || typeof request.lastTurnId !== 'string' || request.lastTurnId.length === 0)) {
    throw new SessionSelectionError('session.lastTurnId is valid only for fork and must be a non-empty string', 'invalid_session_request');
  }
  let context;
  if (request.context !== undefined) {
    if (typeof request.context !== 'object' || request.context === null || Array.isArray(request.context)) {
      throw new SessionSelectionError('session.context must be an object', 'invalid_session_request');
    }
    if (typeof request.context.worktree !== 'string' || request.context.worktree.length === 0) {
  _dispatchPass() {
    for (const taskId of this._taskOrder) {
      const task = this._tasks.get(taskId);
      if (!task || task.status !== 'pending') continue;
      if (task.deps.some((d) => this._tasks.get(d)?.status !== 'completed')) continue;
      const selection = this._resolveVendor(task);
      const vendor = selection?.vendor;
      if (!vendor || !this._adapters[vendor]) continue;
      const card = this._adapters[vendor].card();
      if (this._inFlightCount(vendor) >= card.concurrencyCeiling) continue;
      this._dispatch(task, vendor, selection.model);
    }
  }

  _sweepDeadlines() {
    const now = this._now();
    for (const [requestId, record] of [...this._pending]) {
      if ((record.kind === 'approval' || record.kind === 'publication') && record.state === 'pending' && record.deadlineAt != null && now >= record.deadlineAt) {
        this._resolveRecord(requestId, { decision: 'deny' }, 'policy').catch(noop);
      }
    }
    for (const [workerId, waiter] of [...this._stopWaiters]) {
      if (!waiter.finalized && waiter.deadlineAt != null && now >= waiter.deadlineAt) {
        this._forceStop(workerId, waiter);
      }
    }
  }

  _resolveVendor(task) {
    if (task.vendorRequested !== 'auto') {
      const vendor = task.vendorRequested;
      if (!cardSupportsSession(this._adapters[vendor]?.card(), task.sessionRequest)) return null;
      const resolved = resolveCardModel(this._adapters[vendor]?.card(), task.modelRequested, task.modelPolicy, { explicit: true });
      return resolved.ok ? { vendor, model: resolved.model } : null;
    }
    const cards = {};
    const resolvedModels = {};
    for (const [name, ad] of Object.entries(this._adapters)) {
      const card = ad.card();
      if (!cardSupportsSession(card, task.sessionRequest)) continue;
      const resolved = resolveCardModel(card, task.modelRequested, task.modelPolicy, { explicit: false });
      if (resolved.ok) {
        cards[name] = {
          ...card,
          modelSelection: { ...(card.modelSelection ?? {}), resolved: resolved.model ?? null },
        };
        resolvedModels[name] = resolved.model;
      }
    }
    const inFlight = {};
    for (const name of Object.keys(this._adapters)) inFlight[name] = this._inFlightCount(name);
    const chosen = this._route(task, cards, inFlight);
    if (!chosen || !this._adapters[chosen] || !Object.hasOwn(resolvedModels, chosen)) return null;
    return { vendor: chosen, model: resolvedModels[chosen] };
  }

  _inFlightCount(vendor) {
    let n = 0;
    for (const h of this._workers.values()) {
      if (h.vendor === vendor && (h.status === 'working' || h.status === 'stopping' || h.status === 'blocked')) n++;
    }
    return n;
  }

  _harnessOf(vendor) {
    const card = this._adapters[vendor]?.card();
    return card ? `${card.harness}@${card.version}` : '';
  }

  _dispatch(task, vendor, model) {
    const handle = this._workers.get(task.assignee);
    const workerId = handle.id;
    if (this._coordination) {
      const claim = this._coordination.claimTask(task.id, workerId, task.coordinationVersion, {
        actor: 'orchestrator', key: `task.claimed:${task.id}:${task.coordinationVersion}`,
      });
      task.coordinationVersion = claim.task.version;
    }
    this._fences.register(workerId);
    handle.vendor = vendor;
    handle.modelResolved = model ?? null;
    task.modelResolved = model ?? null;
    const harness = this._harnessOf(vendor);
    let runtime;
    try {
      runtime = this._ensureRuntimeScope(handle);
    } catch (err) {
      try { this._runtimeScopes?.remove?.(workerId); } catch { /* best effort */ }
      const crashEvent = this._log.append({
        worker: workerId, harness, turnEpoch: this._safeTurnEpoch(handle), kind: 'lifecycle.crashed', actor: 'policy',
        payload: { phase: 'runtime_scope', error: String(err?.message ?? err) },
      });
      const evidence = this._coordMapEvent(crashEvent);
      this._coordTransition(task, 'failed', `task.failed:${task.id}:runtime_scope`, evidence);
      task.status = 'failed';
      handle.status = 'exited';
      return;
    }
    if (runtime) task.runtimeScope = handle.runtimeScope;

    // Create the worktree; the returned readiness promise is handed to the adapter so the
    // worker waits for its checkout to exist before touching disk. Status still flips to
    // 'working' and the adapter is invoked synchronously below (so a bare tick() dispatches
    // in one turn), while the worker's actual work is gated on the worktree being ready.
    const worktreeSource = task.sessionRequest?.mode === 'resume'
      ? Promise.resolve({
          path: task.sessionContext.worktree,
          branch: task.sessionContext.branch,
          baseSha: task.sessionContext.baseSha,
          ownerTaskId: task.sessionContext.ownerTaskId,
        })
      : Promise.resolve(this._worktrees.create(task.id));
    const worktreeReady = worktreeSource
      .then(async (res) => {
        if (res && res.path) {
          task.worktree = res.path;
          handle.worktree = res.path;
          const sessionContext = Object.freeze({
            worktree: res.path,
            ...(this._repoRoot ? { repoRoot: this._repoRoot } : {}),
            ...(res.baseSha ? { baseSha: res.baseSha } : {}),
